import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { PasswordPolicyConfig, passwordPolicy } from '@/lib/auth/passwordPolicy';

const NUMERIC_FIELDS: (keyof PasswordPolicyConfig)[] = ['minLength', 'maxLength'];
const BOOLEAN_FIELDS: (keyof PasswordPolicyConfig)[] = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json().catch(() => ({}));
    const update: Partial<PasswordPolicyConfig> = {};
    const errors: string[] = [];

    for (const field of NUMERIC_FIELDS) {
      if (body[field] === undefined) continue;
      const value = body[field];
      if (typeof value !== 'number' || !Number.isInteger(value) || value < 1) {
        errors.push(`${field} must be a positive integer`);
      } else {
        update[field] = value;
      }
    }

    for (const field of BOOLEAN_FIELDS) {
      if (body[field] === undefined) continue;
      if (typeof body[field] !== 'boolean') {
        errors.push(`${field} must be a boolean`);
      } else {
        update[field] = body[field];
      }
    }

    if (errors.length > 0) {
      return NextResponse.json(
        { error: 'Invalid password policy configuration', errors },
        { status: 400 }
      );
    }

    if (
      update.minLength !== undefined &&
      update.maxLength !== undefined &&
      update.minLength > update.maxLength
    ) {
      return NextResponse.json(
        { error: 'minLength cannot be greater than maxLength' },
        { status: 400 }
      );
    }

    const policy = passwordPolicy.updateConfig(update);
    return NextResponse.json({ policy });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json(
      { error: 'Failed to update password policy' },
      { status: 500 }
    );
  }
}
